script:
fleet_event = {
	id = galactic_features.551
	hide_window = yes
	is_triggered_only = yes

	trigger = {
		exists = fromfrom.owner
		is_in_combat = yes
		owner = {
			OR = {
				is_forced_friendly = fromfrom.owner
				is_forced_neutral = fromfrom.owner
			}
		}
	}

	immediate = {
		owner = {
			if = {
				limit = {
					is_forced_friendly = fromfrom.owner
				}
				set_faction_hostility = {
					target = fromfrom.owner
					set_friendly = no
				}
			}
			if = {
				limit = {
					is_forced_neutral = fromfrom.owner
				}
				set_faction_hostility = {
					target = fromfrom.owner
					set_neutral = no
				}
			}
		}
	}
}
